@js:(function(){
  var head='', body='';
  try {
    var raw='';
    try { raw=(typeof result==='undefined'||result===null)?'':String(result); } catch(e0){ raw=''; }
    var j=null;
    try { j=JSON.parse(raw); } catch(e1) { j=null; }
    if(!j && typeof result==='object' && result!==null){ j=result; }
    body = raw ? raw.substring(0,400) : '（空响应：请求未发出/被拦截/超时）';

    var songs=[];
    if(j){ collect(j,0,songs); }

    if(songs.length){
      var out=[];
      for(var i=0;i<songs.length;i++){
        var t=songs[i];
        var k=t.key!=null?String(t.key):(t.id!=null?String(t.id):'');
        var nm=t.name!=null?String(t.name):(t.title!=null?String(t.title):'');
        if(!k||!nm) continue;
        var art='';
        if(t.artistName!=null) art=String(t.artistName);
        else if(t.artist_name!=null) art=String(t.artist_name);
        else if(t.singer!=null) art=String(t.singer);
        var cov='';
        if(t.image!=null) cov=String(t.image);
        else if(t.thumbnail!=null) cov=String(t.thumbnail);
        var du=0;
        try{ du=Number(t.duration)||0; }catch(e2){ du=0; }
        if(du>1000) du=Math.round(du/1000);
        var dur='';
        if(du>0){ var m=Math.floor(du/60), s=du%60; dur=m+'分'+(s<10?'0':'')+s+'秒'; }
        out.push({name:nm, author:art, coverUrl:cov,
          bookUrl:'https://graph.nhaccuatui.com/api/v1/song/detail/'+k+'?key='+k+'&isDailyMix=false&timestamp='+Date.now(),
          lastChapter:dur});
      }
      if(out.length) return out;
    }

    if(!raw){ head='❌ 无返回（请求失败/被拦截/超时）'; }
    else if(raw.indexOf('Request denied')>=0||raw.indexOf('403')>=0){ head='❌ 被拦截（403/网关拒绝）'; }
    else if(raw.indexOf('<html')>=0){ head='❌ 返回HTML页面（可能需验证）'; }
    else if(!j){ head='⚠️ 非JSON返回'; }
    else { head='⚠️ 接口通但结构里没有歌曲'; }
  } catch(e3) {
    head='❌ JS规则执行异常';
    try { body=String(e3); } catch(e4) { body='（异常信息无法读取）'; }
  }
  return [{name:head, author:body, coverUrl:'', bookUrl:'', lastChapter:''}];

  function collect(n,d,res){
    if(d>6||n==null||res.length>200) return;
    if(typeof n!=='object') return;
    var isArr=Object.prototype.toString.call(n)==='[object Array]';
    if(isArr){
      for(var i=0;i<n.length;i++){
        if(isSong(n[i])) res.push(n[i]); else collect(n[i],d+1,res);
      }
      return;
    }
    if(isSong(n)){ res.push(n); return; }
    for(var k in n){ if(Object.prototype.hasOwnProperty.call(n,k)) collect(n[k],d+1,res); }
  }
  function isSong(o){
    if(o==null||typeof o!=='object') return false;
    var hasKey=(o.key!=null)||(o.id!=null);
    var hasName=(o.name!=null)||(o.title!=null)||(o.song_name!=null);
    return hasKey&&hasName;
  }
})();

