ruleContent.content:
@js:(function(){
  try {
    var s='';
    try { s=String((typeof java!=='undefined'&&java&&java.baseUrl)?java.baseUrl:((typeof baseUrl!=='undefined')?baseUrl:'')); } catch(e0){ s=''; }
    if(s.indexOf('#lyric')>=0) return lyric(s);
    return audio(s);
  } catch(e){ return ''; }

  function audio(url){
    var raw='';
    try { raw=String(result||''); } catch(e){ raw=''; }
    if(!raw||raw.indexOf('song')<0){
      try { var r2=String(java.ajax(url)); if(r2) raw=r2; } catch(e1){}
    }
    var j=null;
    try { j=JSON.parse(raw); } catch(e2){ j=null; }
    if(!j) return '';
    var list=[];
    collect(j,0,list,true);
    if(!list.length){
      var m=String(raw).match(/https?:[^"'\\ ]{10,300}?\.(?:mp3|m4a|aac|flac)(?:[^"'\\ ]*)/i);
      return m?m[0]:'';
    }
    var best='',bv=-1;
    for(var i=0;i<list.length;i++){
      var it=list[i];
      if(it.onlyVIP===true||it.only_vip===true||it.vip===true) continue;
      var u=it.stream||it.streamUrl||it.file_url||it.url||'';
      if(!u) continue;
      var q=String(it.type||it.quality||it.bitrate||'');
      var v=1;
      if(/320/.test(q)) v=3; else if(/lossless|flac/i.test(q)) v=4; else if(/128/.test(q)) v=2;
      if(v>bv){bv=v;best=u;}
    }
    return best||'';
  }

  function lyric(url){
    var raw='';
    try { raw=String(java.ajax(url)); } catch(e){ raw=''; }
    var j=null;
    try { j=JSON.parse(raw); } catch(e){ return '（歌词获取失败）'; }
    var t='';
    walk(j,0);
    return t||'（无歌词）';
    function walk(n,d){
      if(t||d>6||n==null) return;
      if(typeof n==='string'){ if(n.length>20){ t=n; } return; }
      if(typeof n!=='object') return;
      var isArr=Object.prototype.toString.call(n)==='[object Array]';
      if(isArr){ for(var i=0;i<n.length;i++) walk(n[i],d+1); return; }
      for(var k in n){ if(Object.prototype.hasOwnProperty.call(n,k)) walk(n[k],d+1); }
    }
  }

  function collect(n,d,res,streamMode){
    if(d>6||n==null||res.length>200) return;
    if(typeof n!=='object') return;
    var isArr=Object.prototype.toString.call(n)==='[object Array]';
    if(isArr){ for(var i=0;i<n.length;i++){ if(isS(n[i])) res.push(n[i]); else collect(n[i],d+1,res,streamMode); } return; }
    if(isS(n)){ res.push(n); return; }
    for(var k in n){ if(Object.prototype.hasOwnProperty.call(n,k)) collect(n[k],d+1,res,streamMode); }
  }
  function isS(o){
    return o&&typeof o==='object'&&(o.stream!=null||o.streamUrl!=null||o.file_url!=null)&&(o.type!=null||o.quality!=null||o.bitrate!=null);
  }
})();
